create extension if not exists "pgcrypto";
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, role text default 'client', phone text, referral_code text unique, created_at timestamptz default now());
create table if not exists projects(id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id) on delete cascade, title text not null, level text, discipline text, status text default 'active', created_at timestamptz default now());
create table if not exists topic_packs(id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id) on delete cascade, input jsonb not null, topics jsonb not null, paid boolean default false, created_at timestamptz default now());
create table if not exists diagnostics(id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id) on delete cascade, project_id uuid references projects(id) on delete set null, input jsonb not null, total_score int, scores jsonb, issues jsonb, created_at timestamptz default now());
create table if not exists consultations(id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id) on delete cascade, diagnostic_id uuid references diagnostics(id) on delete set null, type text, status text default 'requested', scheduled_at timestamptz, notes text, created_at timestamptz default now());
create table if not exists payments(id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id) on delete set null, reference text unique, amount_kobo bigint not null, currency text default 'NGN', purpose text, status text default 'pending', metadata jsonb, created_at timestamptz default now());
create table if not exists subscriptions(id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id) on delete cascade, plan text not null, status text default 'active', starts_at timestamptz default now(), ends_at timestamptz);
create table if not exists referrals(id uuid primary key default gen_random_uuid(), referrer_id uuid references profiles(id) on delete cascade, referred_user_id uuid references profiles(id) on delete set null, code text not null, status text default 'clicked', conversion_value_kobo bigint default 0, created_at timestamptz default now());
create table if not exists rewards(id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id) on delete cascade, referral_id uuid references referrals(id) on delete set null, amount_kobo bigint not null, status text default 'pending', created_at timestamptz default now());